package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	for scanner.Scan() {
		line := scanner.Text()
		parts := strings.Fields(line)
		if len(parts) < 2 {
			continue
		}

		n, _ := strconv.Atoi(parts[0])
		m, _ := strconv.Atoi(parts[1])

		if m == 0 || m == 1 {
			fmt.Println(1)
		} else if n == m {
			fmt.Println(0)
		} else if n/2 > m {
			fmt.Println(m)
		} else {
			fmt.Println(n - m)
		}
	}
}

